import { loadFont as loadExo } from "@remotion/google-fonts/Exo2";
import React from "react";
import { AbsoluteFill, Easing, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import { DroneTop, ItemIcon, Lampada, Loja, Mapa, Palco, Predio, Timeline } from "./Desenhos";
import { V } from "./tempos";

// VISTA 95 · filmagens com drone (Boa Vista, RR). Motion vertical sobre a narração que o cliente mandou pronta.
// Identidade tirada da foto de perfil do Instagram (@suamarca): preto de céu noturno, dourado/laranja, branco, tipografia
// larga e inclinada, drone de frente. O logo aqui é REDESENHADO (só existe a foto de perfil em 100 px): trocar pelo arquivo
// do cliente quando chegar. As imagens aéreas são de banco (Mixkit, uso livre), autorizadas pelo cliente no pedido.
// v2 (pedido: "mais motion, intercalando motion e imagem"): a pergunta, o drone sobre o mapa, a captação/edição e
// as ideias viraram desenho animado (Desenhos.tsx); as imagens aéreas entram entre eles.
// Tempos = tempo da palavra na voz (tempos.ts, medidos em voz-v1.mp3); `t` já desconta a entrada da locução.

const { fontFamily: F } = loadExo("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: FI } = loadExo("italic", { weights: ["800"], subsets: ["latin", "latin-ext"] });

export const V95_FPS = 30;
export const V95_LEAD = 0.5;
export const V95_FRAMES = Math.round((V.fim + 1.8 + V95_LEAD) * V95_FPS);
const fr = (s: number) => Math.max(0, Math.round((s + V95_LEAD) * V95_FPS));

const BG = "#04060B";
const WHITE = "#FFFFFF";
const SOFT = "rgba(255,255,255,0.82)";
const GOLD = "#F6A823";
const GOLD_L = "#FFD27A";
const ORANGE = "#EE7A16";
const GRAD = `linear-gradient(180deg, ${GOLD_L} 0%, ${GOLD} 48%, ${ORANGE} 100%)`;
const MX = 120;
const COL = 840;
const CARD = { x: MX, y: 340, w: COL, h: 1120 };

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const io = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: INOUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const mix = (a: number, b: number, p: number) => a + (b - a) * p;

// texto: entra desfocado com leve escala, assenta e fica parado; sai desfocando no mesmo lugar (nunca desloca)
const txt = (t: number, at: number, out?: number, d = 0.34): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.14);
  return { opacity: Math.min(1, e * 1.7) * (1 - o), filter: `blur(${((1 - e) * 14 + o * 10).toFixed(1)}px)`, transform: `scale(${(0.92 + 0.08 * e).toFixed(4)})` };
};
const goldText: React.CSSProperties = { backgroundImage: GRAD, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" };

const Line: React.FC<{ t: number; at: number; out?: number; top: number; size: number; gold?: boolean; color?: string; weight?: number; caps?: boolean; track?: string; children: React.ReactNode }> = ({ t, at, out, top, size, gold, color = WHITE, weight = 700, caps, track, children }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, textAlign: "center", fontFamily: F, fontWeight: gold ? 800 : weight, fontSize: size, lineHeight: 1.12, letterSpacing: track ?? (caps ? "0.01em" : "-0.01em"), textTransform: caps ? "uppercase" : "none", whiteSpace: "nowrap", ...txt(t, at, out) }}>
    <span style={gold ? goldText : { color }}>{children}</span>
  </div>
);

// trecho de vídeo: começa em `a` (tempo da voz) e a câmera fecha devagar, com um impulso curto na entrada
const Clip: React.FC<{ t: number; src: string; a: number; b: number; rate?: number; from?: number; push?: number; filter?: string }> = ({ t, src, a, b, rate = 1, from = 1.1, push = 0.06, filter }) => (
  <Sequence from={fr(a)} durationInFrames={Math.max(1, fr(b) - fr(a))} layout="none">
    <AbsoluteFill style={{ transform: `scale(${(mix(from, 1, k(t, a, 0.5)) + push * lin(t, a, a + 5)).toFixed(4)})`, filter }}>
      <OffthreadVideo muted src={staticFile(`vista95/${src}.mp4`)} playbackRate={rate} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    </AbsoluteFill>
  </Sequence>
);
const Scrim: React.FC<{ a?: number }> = ({ a = 0.9 }) => (
  <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(4,6,11,0.5) 0%, rgba(4,6,11,0) 20%, rgba(4,6,11,0) 50%, rgba(4,6,11,${a * 0.9}) 74%, rgba(4,6,11,${a}) 100%)` }} />
);
// fundo escuro com um brilho dourado bem leve atrás do elemento principal
const Night: React.FC<{ t: number; cy?: number; a?: number }> = ({ t, cy = 46, a = 0.2 }) => (
  <AbsoluteFill style={{ background: BG }}>
    <AbsoluteFill style={{ background: `radial-gradient(60% 38% at 50% ${cy}%, rgba(246,168,35,${(a + 0.04 * Math.sin(t * 1.6)).toFixed(3)}) 0%, rgba(246,168,35,0) 100%)` }} />
  </AbsoluteFill>
);
// atrás da marca: a cidade à noite, bem escurecida (como na foto de perfil do cliente), com o brilho dourado por cima
const Cidade: React.FC<{ t: number; src: string; a: number; b: number; rate?: number; cy?: number }> = ({ t, src, a, b, rate = 1, cy = 46 }) => (
  <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
    <Clip t={t} src={src} a={a} b={b} rate={rate} from={1.25} push={0.3} filter="saturate(0.8)" />
    <AbsoluteFill style={{ background: "rgba(4,6,11,0.8)" }} />
    <AbsoluteFill style={{ background: `radial-gradient(60% 38% at 50% ${cy}%, rgba(246,168,35,${(0.2 + 0.04 * Math.sin(t * 1.6)).toFixed(3)}) 0%, rgba(246,168,35,0) 100%)` }} />
  </AbsoluteFill>
);
const Card: React.FC<{ children: React.ReactNode; style?: React.CSSProperties }> = ({ children, style }) => (
  <div style={{ position: "absolute", left: CARD.x, top: CARD.y, width: CARD.w, height: CARD.h, borderRadius: 40, overflow: "hidden", background: "#0B0F18", boxShadow: "0 30px 80px rgba(0,0,0,0.6)", ...style }}>{children}</div>
);

// ───────── drone de frente (desenho) e marca redesenhada ─────────
const DroneIcon: React.FC<{ w: number; color?: string; t: number }> = ({ w, color = GOLD, t }) => {
  const spin = 0.35 + 0.65 * Math.abs(Math.sin(t * 38));
  return (
    <svg width={w} height={w * 0.4} viewBox="0 0 200 80" fill="none" stroke={color} strokeWidth={5} strokeLinecap="round" strokeLinejoin="round">
      <path d="M30 32H170" />
      <rect x={78} y={24} width={44} height={22} rx={8} fill={color} />
      <circle cx={100} cy={56} r={7} fill={color} />
      <path d="M30 32v-9M170 32v-9M86 46l-8 18M114 46l8 18" />
      <ellipse cx={30} cy={20} rx={27 * spin} ry={2.5} fill={color} />
      <ellipse cx={170} cy={20} rx={27 * (1.35 - spin)} ry={2.5} fill={color} />
    </svg>
  );
};
const Marca: React.FC<{ t: number; at: number; top: number; size: number }> = ({ t, at, top, size }) => {
  const e = pop(t, at, 0.5);
  const fly = k(t, at - 0.1, 0.7);
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", opacity: Math.min(1, k(t, at, 0.2) * 1.5), transform: `scale(${(0.8 + 0.2 * e).toFixed(4)})` }}>
      <div style={{ transform: `translateY(${((1 - fly) * 90 + Math.sin(t * 2.4) * 7).toFixed(2)}px)` }}><DroneIcon w={size * 1.5} t={t} /></div>
      <div style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 800, fontSize: size, lineHeight: 1, letterSpacing: "-0.01em", whiteSpace: "nowrap", marginTop: size * 0.08 }}>
        <span style={{ color: WHITE }}>VISTA</span>
        <span style={{ ...goldText, paddingRight: size * 0.08 }}>95</span>
      </div>
      <div style={{ width: size * 3.6 * io(t, at + 0.15, 0.5), height: Math.max(4, size * 0.035), borderRadius: 4, background: GRAD, marginTop: size * 0.1 }} />
    </div>
  );
};

// visor de câmera: quatro cantos e o REC piscando (só nas cenas em que a fala é sobre filmar)
const Visor: React.FC<{ t: number; at: number; x: number; y: number; w: number; h: number }> = ({ t, at, x, y, w, h }) => {
  const e = k(t, at, 0.45);
  const L = 70 * e;
  const c = (sx: number, sy: number): React.CSSProperties => ({ position: "absolute", left: sx < 0 ? x : x + w - L, top: sy < 0 ? y : y + h - L, width: L, height: L, borderColor: GOLD, borderStyle: "solid", borderWidth: 0, [sy < 0 ? "borderTopWidth" : "borderBottomWidth"]: 6, [sx < 0 ? "borderLeftWidth" : "borderRightWidth"]: 6, opacity: e });
  const f = Math.max(0, Math.floor((t - at) * V95_FPS));
  const tc = `00:${String(Math.floor(f / 30) % 60).padStart(2, "0")}:${String(f % 30).padStart(2, "0")}`;
  return (
    <>
      <div style={c(-1, -1)} /><div style={c(1, -1)} /><div style={c(-1, 1)} /><div style={c(1, 1)} />
      <div style={{ position: "absolute", left: x + 44, top: y + 40, display: "flex", alignItems: "center", gap: 14, fontFamily: F, fontWeight: 700, fontSize: 34, color: WHITE, letterSpacing: "0.08em", opacity: e, fontVariantNumeric: "tabular-nums", textShadow: "0 2px 10px rgba(0,0,0,0.6)" }}>
        <div style={{ width: 20, height: 20, borderRadius: 10, background: "#FF3B30", opacity: Math.floor((t - at) * 2) % 2 ? 0.25 : 1 }} />REC<span style={{ opacity: 0.85, marginLeft: 10 }}>{tc}</span>
      </div>
    </>
  );
};

// ───────── cena 1 · a pergunta em desenho: o drone ilumina o prédio, o palco e a loja; em "diferente" abre a imagem real ─────────
const ASK = [
  { verb: "destacar sua", noun: "Empresa", at: V.empresa },
  { verb: "divulgar seu", noun: "Evento", at: V.evento },
  { verb: "apresentar seu", noun: "Negócio", at: V.negocio },
];
const S1: React.FC<{ t: number }> = ({ t }) => {
  const ex = io(t, V.diferente - 0.14, 0.55);
  const fly = k(t, -0.45, 0.85);
  const dip = ASK.reduce((m, x) => Math.max(m, t >= x.at ? 1 - k(t, x.at, 0.4) : 0), 0);
  const dx = -150 + 150 * io(t, V.evento - 0.15, 0.4) + 150 * io(t, V.negocio - 0.15, 0.4);
  const X = 540 + dx - (1 - fly) * 620, Y = 640 - (1 - fly) * 260 + Math.sin(t * 2.6) * 10 + dip * 26;
  // câmera da pergunta: fecha um pouco e dá um impulso a cada item falado (em torno do ponto 540×1000)
  const cam = 1.15 + 0.13 * dip + 0.04 * lin(t, -0.5, V.diferente);
  const beam = lin(t, V.empresa - 0.2, V.empresa) * (0.75 + 0.25 * Math.sin(t * 11)) * (1 - lin(t, V.diferente - 0.25, V.diferente - 0.1));
  return (
    <AbsoluteFill>
      <Night t={t} cy={56} />
      <Line t={t} at={-0.4} out={V.diferente - 0.2} top={200} size={38} color={GOLD} weight={700} caps track="0.3em">Você quer</Line>
      {ASK.map((x, i) => {
        const out = i < 2 ? ASK[i + 1].at - 0.12 : V.diferente - 0.2;
        return (
          <React.Fragment key={i}>
            <Line t={t} at={x.at} out={out} top={262} size={62} color={SOFT} weight={600}>{x.verb}</Line>
            <Line t={t} at={x.at + 0.12} out={out} top={336} size={128} gold caps>{x.noun}?</Line>
            {t >= x.at - 0.05 && t < out + 0.2 ? (
              <div style={{ position: "absolute", left: MX, top: 700, width: COL, height: 900, opacity: 1 - lin(t, out, out + 0.14), transformOrigin: "420px 300px", transform: `scale(${(cam * (1 - 0.06 * lin(t, out, out + 0.14))).toFixed(4)})` }}>
                {i === 0 ? <Predio s={t - x.at} /> : i === 1 ? <Palco s={t - x.at} t={t} /> : <Loja s={t - x.at} font={F} />}
              </div>
            ) : null}
          </React.Fragment>
        );
      })}
      <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0, opacity: beam, transformOrigin: "540px 1000px", transform: `scale(${cam.toFixed(4)})` }}>
        <defs><linearGradient id="v95beam" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor={GOLD_L} stopOpacity={0.5} /><stop offset="1" stopColor={GOLD} stopOpacity={0} /></linearGradient></defs>
        <polygon points={`${X},${Y + 40} ${540 + dx * 0.3 - 330},1530 ${540 + dx * 0.3 + 330},1530`} fill="url(#v95beam)" />
      </svg>
      <div style={{ position: "absolute", left: X - 170, top: Y - 68, opacity: 1 - lin(t, V.diferente - 0.2, V.diferente - 0.05), transformOrigin: `${(540 - X + 170).toFixed(1)}px ${(1000 - Y + 68).toFixed(1)}px`, transform: `scale(${cam.toFixed(4)}) rotate(${((1 - fly) * 16 + dip * -5 + Math.sin(t * 1.9) * 2).toFixed(2)}deg)` }}><DroneIcon w={340} t={t} color={GOLD_L} /></div>
      {t >= V.diferente - 0.16 ? (
        <AbsoluteFill style={{ clipPath: `circle(${(ex * 120).toFixed(2)}% at 50% 34%)`, overflow: "hidden" }}>
          <Clip t={t} src="droneC" a={V.diferente - 0.14} b={V.marca + 0.4} from={1.3} push={0.1} />
          <Scrim />
        </AbsoluteFill>
      ) : null}
      <Line t={t} at={V.diferente + 0.05} top={1330} size={64} color={SOFT} weight={600}>de uma maneira</Line>
      <Line t={t} at={V.diferente + 0.3} top={1410} size={124} gold caps>Diferente?</Line>
    </AbsoluteFill>
  );
};

// ───────── cena 2 · a marca, o drone no visor e a cidade vista de cima ─────────
const S2A: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill>
    <Cidade t={t} src="noite2" a={V.marca - 0.16} b={V.oferece + 0.3} cy={44} />
    <Marca t={t} at={V.marca} top={660} size={170} />
    <Line t={t} at={V.marca + 0.45} top={1040} size={40} color={SOFT} weight={600} caps track="0.22em">Drone • Imagens aéreas</Line>
  </AbsoluteFill>
);
const S2B: React.FC<{ t: number }> = ({ t }) => {
  const a = V.oferece;
  const inn = pop(t, a - 0.05, 0.6);
  const ring = ((t - a) % 1.1) / 1.1;
  return (
    <AbsoluteFill>
      <Night t={t} cy={48} a={0.14} />
      <Card>
        <Mapa t={t - a + 2} />
        <div style={{ position: "absolute", left: 420 - 250 * ring - 60, top: 600 - 250 * ring - 60, width: 500 * ring + 120, height: 500 * ring + 120, borderRadius: "50%", border: `5px solid ${GOLD}`, opacity: (1 - ring) * 0.7 * lin(t, a + 0.4, a + 0.7) }} />
        <div style={{ position: "absolute", left: 420 - 230 + 46, top: 600 - 230 + 70, width: 460, height: 460, borderRadius: "50%", background: "radial-gradient(closest-side, rgba(0,0,0,0.55), rgba(0,0,0,0))", transform: "scale(0.8)" }} />
        <div style={{ position: "absolute", left: 420 - 230 + Math.sin(t * 1.7) * 26, top: 600 - 230 + Math.cos(t * 1.3) * 18 + (1 - inn) * 700, transform: `rotate(${(Math.sin(t * 1.1) * 6).toFixed(2)}deg) scale(${(0.7 + 0.3 * inn).toFixed(4)})` }}><DroneTop size={460} t={t} /></div>
      </Card>
      <Visor t={t} at={a + 0.1} x={CARD.x - 26} y={CARD.y - 26} w={CARD.w + 52} h={CARD.h + 52} />
      <Line t={t} at={a + 1.0} top={1520} size={78} weight={700}>Filmagens aéreas</Line>
      <Line t={t} at={a + 2.05} top={1616} size={112} gold caps>com drone</Line>
    </AbsoluteFill>
  );
};
const S2C: React.FC<{ t: number }> = ({ t }) => {
  const a = V.perspectiva;
  const e = io(t, a - 0.1, 1.3);
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `scale(${mix(1.6, 1.04, e).toFixed(4)}) rotate(${mix(-9, 0, e).toFixed(3)}deg)` }}>
        <Clip t={t} src="noite" a={a - 0.14} b={V.realizamos + 0.35} from={1} push={0.3} />
      </AbsoluteFill>
      <Scrim />
      <Line t={t} at={a + 0.36} top={1290} size={72} color={SOFT} weight={600}>Uma nova</Line>
      <Line t={t} at={a + 0.92} top={1372} size={114} gold caps>Perspectiva</Line>
      <Line t={t} at={a + 1.6} top={1530} size={52} color={SOFT} weight={600}>para seus projetos</Line>
    </AbsoluteFill>
  );
};

// ───────── cena 3 · os sete tipos de filmagem, um por batida da fala ─────────
const ITEMS = [
  { w: "Empresas", at: V.i1, src: "c-empresas" },
  { w: "Fachadas comerciais", at: V.i2, src: "c-fachada" },
  { w: "Eventos", at: V.i3, src: "c-eventos" },
  { w: "Inaugurações", at: V.i4, src: "c-inauguracao" },
  { w: "Imóveis", at: V.i5, src: "c-imoveis" },
  { w: "Terrenos", at: V.i6, src: "c-terreno" },
  { w: "Empreendimentos", at: V.i7, src: "c-obra" },
];
const enter = (i: number, e: number): React.CSSProperties => {
  const r = (1 - e) * 100;
  if (i === 0) return { opacity: Math.min(1, e * 2), transform: `scale(${(1.25 - 0.25 * e).toFixed(4)})` };
  if (i % 4 === 1) return { transform: `translateX(${r.toFixed(3)}%)` };
  if (i % 4 === 2) return { transform: `translateY(${r.toFixed(3)}%)` };
  if (i % 4 === 3) return { clipPath: `circle(${(e * 90).toFixed(2)}% at 50% 50%)` };
  return { transform: `translateX(${(-r).toFixed(3)}%)` };
};
const S3: React.FC<{ t: number }> = ({ t }) => {
  const cur = ITEMS.reduce((n, x, i) => (t >= x.at - 0.08 ? i : n), -1);
  const bump = ITEMS.reduce((m, x) => Math.max(m, t >= x.at - 0.08 ? 1 - k(t, x.at - 0.08, 0.3) : 0), 0);
  const seg = (COL - 6 * 12) / 7;
  return (
    <AbsoluteFill>
      <Night t={t} cy={48} a={0.14} />
      <Line t={t} at={V.realizamos} top={236} size={52} color={SOFT} weight={600}>Realizamos filmagens de</Line>
      <Card style={{ transform: `scale(${(0.9 + 0.1 * pop(t, V.realizamos + 0.1, 0.45) - 0.03 * bump).toFixed(4)})`, opacity: lin(t, V.realizamos + 0.1, V.realizamos + 0.3) }}>
        <Clip t={t} src="c-imoveis" a={V.realizamos} b={V.i1 + 0.3} from={1.2} rate={0.8} filter="brightness(0.45) saturate(0.7)" />
        {ITEMS.map((x, i) => (
          <AbsoluteFill key={i} style={enter(i, io(t, x.at - 0.08, 0.3))}><Clip t={t} src={x.src} a={x.at - 0.1} b={i < 6 ? ITEMS[i + 1].at + 0.25 : V.captacao + 0.35} from={1.14} push={0.1} /></AbsoluteFill>
        ))}
        {cur >= 0 ? (
          <div style={{ position: "absolute", left: 36, top: 36, padding: "10px 24px", borderRadius: 40, background: "rgba(4,6,11,0.72)", fontFamily: F, fontWeight: 700, fontSize: 34, color: WHITE, letterSpacing: "0.08em", fontVariantNumeric: "tabular-nums" }}>
            <span style={{ color: GOLD }}>0{cur + 1}</span> / 07
          </div>
        ) : null}
        {cur >= 0 ? (
          <div style={{ position: "absolute", right: 36, bottom: 36, width: 168, height: 168, borderRadius: 84, background: "rgba(4,6,11,0.8)", border: `4px solid ${GOLD}`, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${(0.6 + 0.4 * pop(t, ITEMS[cur].at - 0.05, 0.35)).toFixed(4)})` }}>
            <ItemIcon i={cur} size={104} p={k(t, ITEMS[cur].at, 0.5)} />
          </div>
        ) : null}
      </Card>
      {ITEMS.map((x, i) => (
        <Line key={i} t={t} at={x.at} out={i < 6 ? ITEMS[i + 1].at - 0.1 : undefined} top={x.w.length > 16 ? 1532 : x.w.length > 12 ? 1524 : 1510} size={x.w.length > 16 ? 76 : x.w.length > 12 ? 90 : 112} gold>{x.w}</Line>
      ))}
      {ITEMS.map((x, i) => (
        <div key={i} style={{ position: "absolute", left: MX + i * (seg + 12), top: 1700, width: seg, height: 8, borderRadius: 4, background: "rgba(255,255,255,0.16)", overflow: "hidden", opacity: lin(t, V.realizamos + 0.3, V.realizamos + 0.6) }}>
          <div style={{ width: `${(k(t, x.at, 0.3) * 100).toFixed(2)}%`, height: "100%", background: GOLD }} />
        </div>
      ))}
    </AbsoluteFill>
  );
};

// ───────── cena 4 · captação → edição (a cor entra da esquerda para a direita) → resultado em tela de cinema ─────────
const RES = [
  { w: "Profissional", at: V.profissional, size: 104 },
  { w: "Moderno", at: V.moderno, size: 104 },
  { w: "Cinematográfico", at: V.cinema, size: 84 },
];
const MON = { x: MX, y: 340, w: COL, h: 600 };
const SHOTS = ["c-empresas", "c-inauguracao", "c-imoveis"];
const S4: React.FC<{ t: number }> = ({ t }) => {
  const g = io(t, V.edicao + 0.25, 1.0);
