      {t >= V.realizamos - 0.16 && t < V.captacao + 0.35 ? <AbsoluteFill style={{ clipPath: `inset(0 0 0 ${((1 - wp) * 100).toFixed(3)}%)` }}><S3 t={t} /></AbsoluteFill> : null}
