import React from "react";
import { Easing, interpolate } from "remotion";

// VISTA 95 · desenhos animados (motion) que se alternam com as imagens aéreas: prédio, palco e loja da pergunta,
// drone visto de cima sobre o mapa, cenas captadas e linha do tempo da edição, lâmpada das ideias, ícones dos sete itens.
// `s` = segundos desde a entrada do desenho; `t` = tempo corrido (para o que gira ou balança sem parar).

const GOLD = "#F6A823";
const GOLD_L = "#FFD27A";
const WHITE = "#FFFFFF";
const PANEL = "#111A2C";
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const e = (s: number, a: number, d = 0.4) => interpolate(s, [a, a + d], [0, 1], { ...cl, easing: OUT });
const b = (s: number, a: number, d = 0.4) => interpolate(s, [a, a + d], [0, 1], { ...cl, easing: BACK });
const draw = (p: number) => ({ pathLength: 1, strokeDasharray: 1, strokeDashoffset: 1 - p });
const rnd = (i: number) => { const x = Math.sin(i * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };

const Chao: React.FC<{ s: number }> = ({ s }) => <path d="M60 822H780" stroke="rgba(255,255,255,0.3)" strokeWidth={5} strokeLinecap="round" {...draw(e(s, 0, 0.4))} />;
const stage = { width: 840, height: 900, viewBox: "0 0 840 900", fill: "none" } as const;

// empresa: prédio que sobe e acende as janelas
export const Predio: React.FC<{ s: number }> = ({ s }) => {
  const h = 520 * b(s, 0, 0.5), hl = 300 * e(s, 0.1, 0.45), hr = 380 * e(s, 0.16, 0.45);
  return (
    <svg {...stage}>
      <rect x={170} y={820 - hl} width={130} height={hl} fill="#0C1220" stroke="rgba(255,255,255,0.45)" strokeWidth={4} />
      <rect x={540} y={820 - hr} width={140} height={hr} fill="#0C1220" stroke="rgba(255,255,255,0.45)" strokeWidth={4} />
      <rect x={300} y={820 - h} width={240} height={h} fill={PANEL} stroke={GOLD} strokeWidth={6} />
      {Array.from({ length: 18 }, (_, i) => {
        const c = i % 3, r = Math.floor(i / 3), on = b(s, 0.3 + (17 - i) * 0.03, 0.25);
        return <rect key={i} x={332 + c * 68} y={340 + r * 72} width={40} height={44} rx={5} fill={GOLD} opacity={on * (0.55 + 0.45 * rnd(i))} />;
      })}
      {[0, 1, 2, 3].map((i) => <rect key={i} x={196 + (i % 2) * 44} y={570 + Math.floor(i / 2) * 80} width={26} height={36} fill={WHITE} opacity={0.5 * e(s, 0.5 + i * 0.05, 0.2)} />)}
      {[0, 1, 2, 3, 4, 5].map((i) => <rect key={i} x={566 + (i % 2) * 50} y={490 + Math.floor(i / 2) * 90} width={28} height={40} fill={WHITE} opacity={0.5 * e(s, 0.55 + i * 0.04, 0.2)} />)}
      <Chao s={s} />
    </svg>
  );
};

// evento: palco com treliça, bandeirinhas, refletores, plateia e confete
export const Palco: React.FC<{ s: number; t: number }> = ({ s, t }) => (
  <svg {...stage}>
    {[230, 610].map((x, i) => (
      <g key={x} transform={`rotate(${(Math.sin(t * 3 + i * 2) * 13).toFixed(2)} ${x} 400)`} opacity={e(s, 0.3, 0.3)}>
        <polygon points={`${x},400 ${x - 95},770 ${x + 95},770`} fill={GOLD} opacity={0.22} />
      </g>
    ))}
    <path d="M190 820V400H650V820" stroke="rgba(255,255,255,0.75)" strokeWidth={7} strokeLinejoin="round" {...draw(e(s, 0, 0.5))} />
    <rect x={420 - 270 * e(s, 0.1, 0.4)} y={760} width={540 * e(s, 0.1, 0.4)} height={60} fill={PANEL} stroke={GOLD} strokeWidth={6} />
    {Array.from({ length: 7 }, (_, i) => {
      const u = (i + 0.5) / 7, x = 190 + u * 460, y = 404 + 34 * Math.sin(Math.PI * u), p = b(s, 0.25 + i * 0.05, 0.3);
      return <polygon key={i} points={`${x - 22},${y} ${x + 22},${y} ${x},${y + 46 * p}`} fill={i % 2 ? WHITE : GOLD} opacity={p} transform={`rotate(${(Math.sin(t * 5 + i) * 7).toFixed(2)} ${x} ${y})`} />;
    })}
    {Array.from({ length: 18 }, (_, i) => {
      const y = 390 + ((s * 230 + rnd(i) * 420) % 400);
      return <rect key={i} x={210 + rnd(i + 40) * 420} y={y} width={14} height={8} fill={i % 3 ? GOLD_L : WHITE} opacity={e(s, 0.4, 0.3) * (1 - (y - 390) / 420)} transform={`rotate(${(s * 300 + i * 40) % 360} ${210 + rnd(i + 40) * 420} ${y})`} />;
    })}
    {Array.from({ length: 9 }, (_, i) => {
      const y = 852 - Math.abs(Math.sin(t * 7 + i * 1.3)) * 16 + (1 - e(s, 0.2 + i * 0.03, 0.3)) * 80;
      return <g key={i}><circle cx={180 + i * 60} cy={y} r={22} fill="#1C2740" /><rect x={152 + i * 60} y={y + 20} width={56} height={60} rx={22} fill="#1C2740" /></g>;
    })}
  </svg>
);

// negócio: loja com toldo listrado, vitrine acesa e placa
export const Loja: React.FC<{ s: number; font: string }> = ({ s, font }) => {
  const up = b(s, 0, 0.5);
