// mapa estilizado correndo por baixo do drone (quadras, ruas tracejadas, luzes)
const TILE = 560;
const BLOCKS = [[30, 20, 220, 140], [290, 20, 250, 140], [580, 20, 230, 140], [30, 200, 220, 180], [290, 200, 250, 180], [580, 200, 230, 180], [30, 420, 220, 120], [290, 420, 250, 120], [580, 420, 230, 120]];
export const Mapa: React.FC<{ t: number; speed?: number }> = ({ t, speed = 210 }) => {
  const off = (t * speed) % TILE;
  return (
    <svg width={840} height={1120} viewBox="0 0 840 1120" style={{ position: "absolute", left: 0, top: 0, background: "#080C15" }}>
      <g transform={`translate(0 ${off.toFixed(2)})`}>
        {[-1, 0, 1, 2].map((n) => (
          <g key={n} transform={`translate(0 ${n * TILE})`}>
            {BLOCKS.map(([x, y, w, h], i) => (
              <g key={i}>
                <rect x={x} y={y} width={w} height={h} rx={14} fill={PANEL} stroke="rgba(255,255,255,0.09)" strokeWidth={2} />
                <rect x={x + 18} y={y + 16} width={w * (0.3 + 0.25 * rnd(i))} height={h * 0.42} rx={6} fill="#1A2743" />
                <rect x={x + w * 0.62} y={y + h * 0.4} width={w * 0.28} height={h * 0.44} rx={6} fill="#172238" />
                <circle cx={x + w * (0.2 + 0.6 * rnd(i + 9))} cy={y + h * 0.8} r={5} fill={GOLD} opacity={0.75} />
                <circle cx={x + w * 0.85} cy={y + h * 0.2} r={4} fill={GOLD_L} opacity={0.5} />
              </g>
            ))}
            <path d={`M270 0V${TILE}M560 0V${TILE}`} stroke="rgba(255,255,255,0.2)" strokeWidth={4} strokeDasharray="22 22" />
            <path d="M0 180H840M0 400H840" stroke="rgba(255,255,255,0.12)" strokeWidth={3} strokeDasharray="16 20" />
          </g>
        ))}
      </g>
    </svg>
  );
};

// linha do tempo da edição: três cortes entram, faixa de título, onda do som e a agulha andando
export const Timeline: React.FC<{ s: number; t: number; play: number }> = ({ s, t, play }) => {
  const clips = [[40, 236], [284, 300], [592, 208]];
  const x = 40 + 760 * play;
  return (
    <svg width={840} height={440} viewBox="0 0 840 440" fill="none">
      {Array.from({ length: 20 }, (_, i) => <path key={i} d={`M${40 + i * 40} 30v${i % 5 ? 12 : 24}`} stroke="rgba(255,255,255,0.3)" strokeWidth={3} strokeLinecap="round" opacity={e(s, i * 0.015, 0.2)} />)}
      {clips.map(([cx, w], i) => {
        const p = b(s, 0.05 + i * 0.14, 0.34);
        return (
          <g key={i} opacity={Math.min(1, p * 1.5)} transform={`translate(${((1 - p) * 120).toFixed(2)} 0)`}>
            <rect x={cx} y={80} width={w} height={100} rx={14} fill={GOLD} />
            <rect x={cx + 10} y={90} width={w - 20} height={80} rx={8} fill="rgba(10,15,26,0.28)" />
            {Array.from({ length: Math.floor(w / 46) }, (_, j) => <rect key={j} x={cx + 16 + j * 46} y={98} width={36} height={64} rx={5} fill="rgba(255,255,255,0.3)" />)}
          </g>
        );
      })}
      {[[120, 190], [470, 250]].map(([cx, w], i) => <rect key={i} x={cx} y={204} width={w * e(s, 0.4 + i * 0.15, 0.35)} height={56} rx={12} fill="rgba(255,255,255,0.85)" />)}
      {Array.from({ length: 76 }, (_, i) => {
        const h = (12 + 78 * rnd(i) * (0.55 + 0.45 * Math.sin(i * 0.5))) * (0.75 + 0.25 * Math.sin(t * 9 + i)), on = 40 + i * 10 < 40 + 760 * e(s, 0.3, 0.7);
        return on ? <rect key={i} x={40 + i * 10} y={340 - h / 2} width={6} height={h} rx={3} fill={40 + i * 10 < x ? GOLD_L : "rgba(246,168,35,0.45)"} /> : null;
      })}
      <g opacity={e(s, 0.15, 0.2)}>
        <path d={`M${x} 26V412`} stroke={WHITE} strokeWidth={5} strokeLinecap="round" />
        <path d={`M${x - 16} 12h32l-16 22z`} fill={WHITE} />
      </g>
    </svg>
  );
};

